struct Tick { double px; long long qty; };

template <class Derived>
struct Handler {
    inline void process(const Tick& t) noexcept {
        // ... common pre-work (timestamp, validation) ...
        static_cast<Derived*>(this)->onTick(t);   // static, inlinable dispatch
        // ... common post-work (metrics) ...
    }
};

struct MyStrategy : Handler<MyStrategy> {
    double position = 0;
    inline void onTick(const Tick& t) noexcept {
        // type-specific hot-path logic, no virtual call
        if (t.px < fair_) position += t.qty;
    }
    double fair_ = 100.0;
};

// Usage: MyStrategy s; s.process(tick);  // onTick resolved & inlined at compile time
